const fs=require('fs'),path=require('path'),cp=require('child_process');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/pages/internal-list-pages.css',SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB;
const PAGES=['admin-anuncio-revisao.html','admin-pedidos-operacao.html','admin-verificacao.html','admin.html','carteira.html','comunidade-interna.html','comunidade.html','configuracoes.html','mensagens.html','meu-perfil.html','notificacoes.html','pedidos.html','perfil-cliente.html','perfil-profissional.html','perfil.html'];
const DIRECT_IMPORTERS=['assets/css/pages/comunidade-foundation.css','assets/css/pages/internal-foundation.css'];
const VIEWPORTS=[359,430,759,760,761,1023,1024,1025,1280,1440];
const SELECTORS={search:'.orders-page-header__search',input:'.orders-header-search input',close:'.orders-header-search__close',actions:'.orders-page-header__actions',bar:'.orders-page-header__bar',heading:'.orders-page-header__heading',h2:'.orders-page-header__heading h2',count:'.orders-page-header__count'};
const EXPECTED_LINES='109,110,111,112,113,158,159,161,162,163,164,165,166,179,183,184,185,186,187,188,189,202,203,204,205,298,299,300,301,302,306,307,308,309,313,314,315,316,317,318,322,323,324,325,326,327,328,329,330,331,332,333';
const sh=c=>cp.execSync(c,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim(),assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important,winnerSelector:l.selector,winnerContext:l.context});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v)}return out}
function verifyReach(){const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8')),tracked=new Set(sh('git ls-files -z assets/css').split('\0').filter(f=>f.endsWith('.css'))),direct=[...tracked].filter(f=>importsFor(f,tracked).includes(TARGET)).sort();assert(JSON.stringify(direct)===JSON.stringify([...DIRECT_IMPORTERS].sort()),`direct importer drift ${JSON.stringify(direct)}`);const reached=[];for(const p of report.pageAssets){const seen=new Set(),todo=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(todo.length){const f=todo.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break}for(const n of importsFor(f,tracked))todo.push(n)}if(hit)reached.push(p.page)}reached.sort();assert(JSON.stringify(reached)===JSON.stringify([...PAGES].sort()),`active reach drift ${JSON.stringify(reached)}`);console.log(`STATIC REACH PASS|pages=${reached.join(',')}|directImporters=${direct.join(',')}|target=${TARGET}|affectedFamilies=9`)}
function verifyDead(p){assert(p.declarations.length===515&&p.dead.length===52,`parse drift ${p.declarations.length}/${p.dead.length}`);assert(p.dead.map(d=>d.line).join(',')===EXPECTED_LINES,'dead line drift');assert(new Set(p.dead.map(d=>d.selector)).size===9,'family drift');for(const d of p.dead){assert(!d.context,`unexpected context ${d.context}`);assert(d.winnerLine>d.line&&!d.important&&!d.winnerImportant,`cascade drift ${d.line}`)}const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===40&&p.dead.length-identical===12,`winner counts drift ${identical}/${p.dead.length-identical}`);console.log(`DEAD ROWS PASS|decl=515|dead=52|families=9|identical=40|changed=12|contexts=global52|lines=${EXPECTED_LINES}`)}
function removeDead(p){const src=fs.readFileSync(TARGET,'utf8'),nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(`${d.property}:`),`line mismatch ${d.line}`);lines.splice(d.line-1,1)}fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/),after=parse(fs.readFileSync(TARGET,'utf8'));assert(stat[0]==='0'&&stat[1]==='52'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);assert(after.declarations.length===463&&after.dead.length===0,`after drift ${after.declarations.length}/${after.dead.length}`);console.log('EPHEMERAL DELTA PASS|file=internal-list-pages.css|additions=0|deletions=52|decl=515->463|dead=52->0')}
async function prep(page){await page.evaluate(()=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');const s=document.createElement('style');s.setAttribute('data-ux049-freeze','');s.textContent='*,*::before,*::after{transition-duration:0s!important;transition-delay:0s!important;animation-duration:0s!important;animation-delay:0s!important}';document.head.appendChild(s)})}
async function captureState(page,pageName,width,state){return page.evaluate(({pageName,width,state,SELECTORS})=>{const round=n=>Math.round(n*1000)/1000;const props=['display','position','width','minWidth','maxWidth','height','minHeight','maxHeight','paddingTop','paddingRight','paddingBottom','paddingLeft','marginLeft','gap','flex','flexWrap','alignItems','justifyContent','borderRadius','backgroundColor','color','fontSize','fontWeight','lineHeight','letterSpacing','opacity','pointerEvents','overflowX','overflowY','boxShadow'];const pick=sel=>{const el=document.querySelector(sel);if(!el)return null;const s=getComputedStyle(el),r=el.getBoundingClientRect(),o={tag:el.tagName,className:typeof el.className==='string'?el.className:''};for(const p of props)o[p]=s[p];o.rect=[round(r.x),round(r.y),round(r.width),round(r.height)];o.scroll=[el.scrollWidth,el.scrollHeight,el.clientWidth,el.clientHeight];return o};const input=document.querySelector(SELECTORS.input),pseudo=input?getComputedStyle(input,'::placeholder'):null;const elements={};for(const [k,v] of Object.entries(SELECTORS))elements[k]=pick(v);return{page:pageName,width,state,elements,placeholder:input?{color:pseudo.color,fontSize:pseudo.fontSize,fontWeight:pseudo.fontWeight,opacity:pseudo.opacity}:null,root:{overflowX:getComputedStyle(document.documentElement).overflowX,overflowY:getComputedStyle(document.documentElement).overflowY},body:{overflowX:getComputedStyle(document.body).overflowX,overflowY:getComputedStyle(document.body).overflowY},doc:{clientWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,clientHeight:document.documentElement.clientHeight,scrollHeight:document.documentElement.scrollHeight,bodyScrollWidth:document.body.scrollWidth,bodyScrollHeight:document.body.scrollHeight}}},{pageName,width,state,SELECTORS})}
function verifyCoverage(snaps){const vals=Object.values(snaps),expected=PAGES.length*VIEWPORTS.length;assert(vals.length===expected,`sample drift ${vals.length}/${expected}`);for(const p of PAGES)assert(vals.filter(s=>s.page===p).length===VIEWPORTS.length,`page coverage ${p}`);const covered=new Set();for(const s of vals){for(const [k,v] of Object.entries(s.default.elements))if(v)covered.add(k);if(s.default.placeholder)covered.add('placeholder')}for(const k of [...Object.keys(SELECTORS),'placeholder'])assert(covered.has(k),`family uncovered ${k}`);console.log(`RUNTIME FAMILY COVERAGE PASS|families=9/9|reachPages=15|samplePages=${PAGES.length}|viewports=${VIEWPORTS.length}|covered=${[...covered].sort().join(',')}`)}
async function capture(browser,tag){const out={};let n=0,overflow=0;for(const pageName of PAGES)for(const width of VIEWPORTS){const ctx=await browser.newContext({viewport:{width,height:1000},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort()});await page.goto(`http://127.0.0.1:4173/${pageName}?ux049-${tag}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});await prep(page);await page.waitForTimeout(20);const def=await captureState(page,pageName,width,'default');if(def.doc.scrollWidth>def.doc.clientWidth+1)overflow++;let interactive=null;if(await page.$(SELECTORS.search)){await page.evaluate(()=>document.querySelector('.orders-page')?.classList.add('is-search-open'));try{await page.hover(SELECTORS.search,{timeout:1000})}catch{}try{await page.focus(SELECTORS.input,{timeout:1000})}catch{}await page.waitForTimeout(20);interactive=await captureState(page,pageName,width,'search-focus')}out[`${pageName}:${width}`]={default:def,interactive};n++;await ctx.close()}verifyCoverage(out);console.log(`RUNTIME CAPTURE|tag=${tag}|pages=15|viewports=${VIEWPORTS.join(',')}|samples=${n}|baselineOverflowSamples=${overflow}`);return out}
(async()=>{assert(SHA&&BLOB,'missing env');assert(sh('git rev-parse HEAD')===SHA,'wrong HEAD');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');verifyReach();const parsed=parse(fs.readFileSync(TARGET,'utf8'));verifyDead(parsed);const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');console.log(`CASCADE RUNTIME PARITY PASS|runtimeDiffs=0|families=9/9|reachPages=15|viewports=${VIEWPORTS.length}|beforeSamples=${Object.keys(before).length}|afterSamples=${Object.keys(after).length}|states=default+search-focus|boundaries=759/760/761+1023/1024/1025|staticCascadeRows=52|identicalWinners=40|changedWinners=12`)}finally{await browser.close()}}finally{server.kill('SIGTERM')}sh(`git reset --hard ${SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===SHA&&sh(`git hash-object ${TARGET}`)===BLOB&&sh('git status --porcelain')==='','restore drift');console.log(`CHECKPOINT PASS|sha=${SHA}|productMutation=0|issueCreated=0|prCreated=0`)})().catch(e=>{console.error(e.stack||e);process.exit(1)});
